<?php
require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/admin-layout.php';admin_required();$keys=['hero_heading','hero_description','hero_cta','hero_link','about_text'];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{foreach($keys as $k){$q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$q->execute([$k,trim($_POST[$k]??'')]);}$img=upload_image($_FILES['hero_image']??[],'banners');if($img){$q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$q->execute(['hero_image','uploads/banners/'.$img]);}flash('Homepage content saved.');redirect('homepage.php');}catch(Throwable $e){$error=$e->getMessage();}}admin_header('Homepage editor');if($error)echo '<div class="notice error">'.e($error).'</div>'; ?><form method="post" enctype="multipart/form-data" class="admin-form admin-panel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><?php foreach($keys as $k):?><label><?=e(ucwords(str_replace('_',' ',$k)))?><?php if(str_contains($k,'description')||str_contains($k,'text')):?><textarea name="<?=$k?>"><?=e(setting($pdo,$k))?></textarea><?php else:?><input name="<?=$k?>" value="<?=e(setting($pdo,$k))?>"><?php endif;?></label><?php endforeach;?><label>Hero image (JPG, PNG, WEBP; max 5 MB)<input type="file" name="hero_image" accept="image/jpeg,image/png,image/webp"></label><button class="button">SAVE HOMEPAGE</button></form><?php admin_footer(); ?>
